import{_ as n}from"./chunks/2.B74ApmNY.js";import{_ as o}from"./chunks/1.DPUt95ua.js";import{_ as r,a as s,b as l,c as d,d as c,e as h,f as g,g as p,h as m,i as u,j as b,k as y,l as f,m as _,n as x}from"./chunks/image15.DMBRmqnC.js";import{_ as e}from"./chunks/image.mtVmn3vQ.js";import{_ as w}from"./chunks/image9.DCHvWr-H.js";import{_ as k}from"./chunks/100.DC6t8P7m.js";import{_ as q}from"./chunks/community.CGfILmM2.js";import{_ as P,C as v,o as z,c as A,ak as a,E as T}from"./chunks/framework.CaWw1yIg.js";const j="/projects/AiBlock/en/standard-kit/assets/1.D48C4KUg.webp",B="/projects/AiBlock/en/standard-kit/assets/image.BqSJICR_.webp",C="/projects/AiBlock/en/standard-kit/assets/image3.QS6usjTG.webp",S="/projects/AiBlock/en/standard-kit/assets/7.DXoZSYJe.webp",D="/projects/AiBlock/en/standard-kit/assets/6.qd5xgB4p.webp",L="/projects/AiBlock/en/standard-kit/assets/4.DkqimdhX.webp",I="/projects/AiBlock/en/standard-kit/assets/8.UIAeBfKv.webp",X=JSON.parse('{"title":"3.2 Music Box","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Builds/3.2 Music Box.md","filePath":"docs/3. Creative Builds/3.2 Music Box.md"}'),M={name:"docs/3. Creative Builds/3.2 Music Box.md"};function O(U,t,$,E,G,W){const i=v("Pdf");return z(),A("div",null,[t[0]||(t[0]=a('<h1 id="_3-2-music-box" tabindex="-1">3.2 Music Box <a class="header-anchor" href="#_3-2-music-box" aria-label="Permalink to &quot;3.2 Music Box&quot;">​</a></h1><h2 id="_3-2-1-lesson-introduction" tabindex="-1">3.2.1 Lesson Introduction <a class="header-anchor" href="#_3-2-1-lesson-introduction" aria-label="Permalink to &quot;3.2.1 Lesson Introduction&quot;">​</a></h2><p>This lesson introduces the interface and functions of the WonderLab programming platform. Learners explore fundamental code blocks and the method for adding controller extension libraries, build a mechanical music box, and complete stepped hands-on tasks including button-triggered sound generation and melody programming. As an introductory programming lesson, it establishes foundational programming logic and builds solid software operation skills.</p><img loading="lazy" height="1662" width="1662" src="'+n+'" class="common_img" style="width:400px;"><h2 id="_3-2-2-learning-objectives" tabindex="-1">3.2.2 Learning Objectives <a class="header-anchor" href="#_3-2-2-learning-objectives" aria-label="Permalink to &quot;3.2.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Master the interface layout and functions of WonderLab. Understand button-triggered event concepts. Learn buzzer pitch parameters. Grasp the program download process and port selection methods.</p></li><li><p><strong>Skill Objectives</strong>: Create programming projects independently. Add device extension libraries proficiently. Master block snapping operations. Write, download, and run button-buzzer programs.</p></li><li><p><strong>Thinking Objectives</strong>: Build event-driven and sequential execution programming thinking. Understand sequential program structure. Learn problem decomposition to foster computational thinking and coding confidence.</p></li><li><p><strong>Application Objectives</strong>: Understand practical applications of buzzers in home appliances. Clarify how programming controls electronic devices. Stimulate interest in exploring smart devices.</p></li></ol><h2 id="_3-2-3-preparation" tabindex="-1">3.2.3 Preparation <a class="header-anchor" href="#_3-2-3-preparation" aria-label="Permalink to &quot;3.2.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-2-4-hands-on-project" tabindex="-1">3.2.4 Hands-On Project <a class="header-anchor" href="#_3-2-4-hands-on-project" aria-label="Permalink to &quot;3.2.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson uses buttons to control the buzzer for playing music, adopting an &quot;event trigger and sequential execution&quot; structure. Pressing the left button triggers the program, which executes multiple &quot;play note&quot; blocks in sequence, paired with wait blocks to regulate note duration and form a complete melody. Programming the melody of &quot;Twinkle Twinkle Little Star&quot; provides an intuitive understanding of the step-by-step execution rule in computer programs.</p><h3 id="_2-programming-software-introduction" tabindex="-1">(2) Programming Software Introduction <a class="header-anchor" href="#_2-programming-software-introduction" aria-label="Permalink to &quot;(2) Programming Software Introduction&quot;">​</a></h3><ol><li>WonderLab is a dedicated Scratch-based graphical programming software designed for Hiwonder products. The software supports bidirectional conversion between graphical blocks and Python code. Dragging and snapping instruction blocks allows intuitive program authoring, which suits beginners learning programming.</li></ol><img loading="lazy" height="1017" width="1920" src="'+o+'" class="common_img" style="width:600px;"><ol start="2"><li>The figure below illustrates the functional areas of the WonderLab software: ① Menu bar, ② Block palette, ③ Script area, and ④ Code display and upload area.</li></ol><img loading="lazy" height="1040" width="1920" src="'+r+'" class="common_img" style="width:600px;"><ol start="3"><li>The corresponding functions are detailed in the table below:</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="66" width="105" src="'+s+'" class="inline-icon"></td><td style="text-align:left;">Creates, saves, and opens project files</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="105" src="'+l+'" class="inline-icon"></td><td style="text-align:left;">Used for online mode, for informational reference only</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="222" src="'+d+'" class="inline-icon"></td><td style="text-align:left;">Connects or disconnects the device and selects the communication port</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="105" src="'+c+'" class="inline-icon"></td><td style="text-align:left;">Accesses help documentation, checks for updates, and installs drivers</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="225" src="'+h+'" class="inline-icon"></td><td style="text-align:left;">Displays the project file name, showing &quot;scratch project&quot; when unsaved</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="325" src="'+g+'" class="inline-icon"></td><td style="text-align:left;">Switches the workspace between <strong>Online Mode</strong> and <strong>Upload Mode</strong></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="65" src="'+p+'" class="inline-icon"></td><td style="text-align:left;">Set the interface display language to English</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="77" src="'+m+'" class="inline-icon"></td><td style="text-align:left;">Undoes or redoes recent editing actions</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="380" src="'+u+'" class="inline-icon"></td><td style="text-align:left;">Mode toggle button, where <strong>Auto</strong> transforms block programs into Python code, and <strong>Python Coding</strong> allows direct editing in Python</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="66" src="'+b+'" class="inline-icon"></td><td style="text-align:left;">Saves the project as a Python source file</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="66" src="'+y+'" class="inline-icon"></td><td style="text-align:left;">Opens an existing Python file</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="66" src="'+f+'" class="inline-icon"></td><td style="text-align:left;">Interacts with hardware and uploads programs to the controller</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="66" width="66" src="'+_+'" class="inline-icon"></td><td style="text-align:left;">Adds device extension packages</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="198" width="66" src="'+x+'" class="inline-icon"></td><td style="text-align:left;">Zooms in, zooms out, or resets the script editing canvas zoom level</td></tr></tbody></table><h3 id="_3-assembly-guide" tabindex="-1">(3) Assembly Guide <a class="header-anchor" href="#_3-assembly-guide" aria-label="Permalink to &quot;(3) Assembly Guide&quot;">​</a></h3>',22)),T(i,{src:"../../_static/shared/pdf/chapter_3/2.pdf"}),t[1]||(t[1]=a('<h3 id="_4-core-blocks" tabindex="-1">(4) Core Blocks <a class="header-anchor" href="#_4-core-blocks" aria-label="Permalink to &quot;(4) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="59" width="179" src="'+j+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="108" src="'+B+'"></td><td style="text-align:left;">Pauses program execution for a specified duration</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="59" width="554" src="'+C+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+e+'"></td><td style="text-align:left;">Plays notes according to the specified pitch, beat, and playback mode</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="193" width="589" src="'+w+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+e+'"></td><td style="text-align:left;">Triggers corresponding blocks when the button is short-pressed</td></tr></tbody></table><h3 id="_5-program-description-and-upload" tabindex="-1">(5) Program Description and Upload <a class="header-anchor" href="#_5-program-description-and-upload" aria-label="Permalink to &quot;(5) Program Description and Upload&quot;">​</a></h3><ul><li>Sheet Music to Program Pitch Conversion</li></ul><table tabindex="0"><thead><tr><th style="text-align:center;">C4</th><th style="text-align:center;">D4</th><th style="text-align:center;">E4</th><th style="text-align:center;">F4</th><th style="text-align:center;">G4</th><th style="text-align:center;">A4</th><th style="text-align:center;">B4</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">2</td><td style="text-align:center;">3</td><td style="text-align:center;">4</td><td style="text-align:center;">5</td><td style="text-align:center;">6</td><td style="text-align:center;">7</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:center;">Standard Sheet Music</th><th style="text-align:center;">Program Sheet Music</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="247" width="398" src="'+S+'" style="width:435px;"></td><td style="text-align:center;"><img loading="lazy" height="272" width="454" src="'+D+'" style="width:500px;"></td></tr></tbody></table><ul><li>Program Schematic</li></ul><img loading="lazy" height="350" width="430" src="'+L+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>After powering on, short-pressing the left button serves as the startup trigger condition. Once triggered, the program plays notes C4, C4, G4, G4, A4, A4, and G4 in sequence. All notes are set to a beat of one-half with the mode set to background playback. A wait of 0.6 s follows each note playback, completing the corresponding melody.</p></li></ul><img loading="lazy" height="622" width="595" src="'+I+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+k+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1xyD_-3msc3KcaGQHLqkcPOZNSNXFIirT?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-2-5-expansion-and-challenge" tabindex="-1">3.2.5 Expansion and Challenge <a class="header-anchor" href="#_3-2-5-expansion-and-challenge" aria-label="Permalink to &quot;3.2.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Full Performance of Twinkle Twinkle Little Star</strong></p><p>Find the full sheet music for &quot;Twinkle Twinkle Little Star&quot; and add the remaining notes into the program, enabling the buzzer to play the entire song. Adjust the beat length and wait time of each note to enhance melodic rhythm. Incorporate volume changes with louder dynamics during climaxes and softer tones toward the end, practicing richer music programming techniques.</p><p><strong>Project 2: Dual-Button Doorbell Design</strong></p><p>Design a dual-tone doorbell program: pressing the left button plays a high-pitched &quot;ding-dong&quot; chime, while pressing the right button plays a low-pitched &quot;dong-dong&quot; chime. Use different pitch tones to distinguish between front and back doors, or assign the left button as a guest greeting and the right button as an alarm alert. This project exercises programming independent events and reinforces understanding of multi-event parallel structures.</p><h2 id="_3-2-6-q-a" tabindex="-1">3.2.6 Q&amp;A <a class="header-anchor" href="#_3-2-6-q-a" aria-label="Permalink to &quot;3.2.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: After opening WonderLab, what critical step must be completed before the buzzer programming blocks appear?</strong></p><p>Answer: The &quot;AI Blocks Board&quot; extension library must be added first. Hardware features such as the buzzer and buttons are specific to the AiBlock controller, meaning default block libraries do not contain these instructions. Click the Extensions button in the lower-left corner, locate and add &quot;AI Blocks Board&quot; under the Controller category. The onboard resources and button blocks will then appear in the left palette, enabling programs to control the buzzer and buttons. This resembles installing a printer driver before using a printer, serving as the essential first step in hardware programming.</p><p><strong>Question 2: What is the purpose of the block &quot;when left button is short-pressed&quot;? Why must programs be placed beneath it?</strong></p><p>Answer: This is an event-trigger block that functions as a program start switch. All blocks placed beneath it execute once only when the left button is pressed. Without an event block, programs run immediately upon power-up, causing the buzzer to sound continuously without stopping. Using button events provides control over execution timing: press to play, and release to keep silent. This demonstrates the fundamental logic of interactive programming where a trigger signal prompts a machine action.</p><h2 id="_3-2-7-technical-support-and-product-discussion" tabindex="-1">3.2.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-2-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.2.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+q+'" class="common_img" style="width:800px;"></a>',26))])}const Z=P(M,[["render",O]]);export{X as __pageData,Z as default};
